class ICommandBuffer {
 public:
  explicit ICommandBuffer(CommandBufferDesc iDesc) : desc(std::move(iDesc)) {}
  virtual ~ICommandBuffer() = default;

  virtual std::unique_ptr<IRenderCommandEncoder> createRenderCommandEncoder(
      const RenderPassDesc& renderPass,
      const std::shared_ptr<IFramebuffer>& framebuffer,
      const Dependencies& dependencies,
      Result* IGL_NULLABLE outResult = nullptr) = 0;

  std::unique_ptr<IRenderCommandEncoder> createRenderCommandEncoder(
      const RenderPassDesc& renderPass,
      const std::shared_ptr<IFramebuffer>& framebuffer,
      Result* IGL_NULLABLE outResult = nullptr) {
    return createRenderCommandEncoder(renderPass, framebuffer, Dependencies(), outResult);
  }

  virtual std::unique_ptr<IComputeCommandEncoder> createComputeCommandEncoder() = 0;

  virtual void present(const std::shared_ptr<ITexture>& surface) const = 0;

  virtual void waitUntilScheduled() = 0;

  virtual void waitUntilCompleted() = 0;

  virtual void pushDebugGroupLabel(const char* IGL_NONNULL label,
                                   const igl::Color& color = Color(1, 1, 1, 1)) const = 0;

  virtual void popDebugGroupLabel() const = 0;

  virtual void copyBuffer(IBuffer& src,
                          IBuffer& dst,
                          uint64_t srcOffset,
                          uint64_t dstOffset,
                          uint64_t size) = 0;

  virtual void copyTextureToBuffer(ITexture& src,
                                   IBuffer& dst,
                                   uint64_t dstOffset,
                                   uint32_t level = 0,
                                   uint32_t layer = 0) = 0;

  [[nodiscard]] uint32_t getCurrentDrawCount() const {
    return statistics_.currentDrawCount;
  }

  void incrementCurrentDrawCount() {
    statistics_.currentDrawCount++;
  }

  const CommandBufferDesc desc;
  const std::shared_ptr<ITimer> timer;

 private:
  CommandBufferStatistics statistics_;

  friend class ICommandQueue;
};

struct Dependencies {
  static constexpr uint32_t kIglMaxTextureDependencies = 8;
  static constexpr uint32_t kIglMaxBufferDependencies = 8;
  // Note: please ensure that both arrays are dense, meaning that processing will halt immediately
  // if any NULL texture or buffer is encountered.
  ITexture* IGL_NULLABLE textures[kIglMaxTextureDependencies] = {};
  IBuffer* IGL_NULLABLE buffers[kIglMaxBufferDependencies] = {};
  const Dependencies* IGL_NULLABLE next = nullptr; // optional extra dependencies
};

struct BindGroupTextureDesc {
  std::shared_ptr<ITexture> textures[IGL_TEXTURE_SAMPLERS_MAX] = {};
  std::shared_ptr<ISamplerState> samplers[IGL_TEXTURE_SAMPLERS_MAX] = {};
  std::string debugName;
};

struct BindGroupBufferDesc {
  std::shared_ptr<IBuffer> buffers[IGL_UNIFORM_BLOCKS_BINDING_MAX] = {};
  size_t offset[IGL_UNIFORM_BLOCKS_BINDING_MAX] = {};
  size_t size[IGL_UNIFORM_BLOCKS_BINDING_MAX] = {}; // 0 means the remaining size from `offset` to
                                                    // the end of the buffer
  uint32_t isDynamicBufferMask = 0; // one bit per each buffer
  std::string debugName;
};

class ICommandEncoder {
 public:
  explicit ICommandEncoder(std::shared_ptr<ICommandBuffer> commandBuffer) :
    commandBuffer_(std::move(commandBuffer)) {}

  virtual ~ICommandEncoder() = default;

  /**
   * Declares the end of commands generated by this instance of the encoder.
   *
   * After endEncoding() is called, the encoder is invalid. You must create
   * another encoder to submit more commands.
   */
  virtual void endEncoding() = 0;

  /**
   * Pushes a debug label onto a stack of debug string labels into the captured frame data.
   *
   * If supported by the backend GPU driver, this allows you to easily associate subsequent
   * commands in the captured call stack with this label.
   *
   * When all commands for this label have been sent to the encoder, call popDebugGroupLabel()
   * to pop the label off the stack.
   */
  virtual void pushDebugGroupLabel(const char* IGL_NONNULL label,
                                   const igl::Color& color = Color(1, 1, 1, 1)) const = 0;

  /**
   * Inserts a debug label into the captured frame data.
   *
   * If supported by the backend GPU driver, this allows you to easily insert a label into the
   * call stack of the captured frame data.
   */
  virtual void insertDebugEventLabel(const char* IGL_NONNULL label,
                                     const igl::Color& color = Color(1, 1, 1, 1)) const = 0;

  /**
   * Pops a most recent debug label off a stack of debug string labels.
   *
   * This should be preceded by pushDebugGroupLabel().
   */
  virtual void popDebugGroupLabel() const = 0;

  ICommandBuffer& getCommandBuffer() {
    IGL_DEBUG_ASSERT(commandBuffer_);
    return *commandBuffer_;
  }

  [[nodiscard]] const std::shared_ptr<ICommandBuffer>& getCommandBufferPtr() const {
    IGL_DEBUG_ASSERT(commandBuffer_);
    return commandBuffer_;
  }

 private:
  std::shared_ptr<ICommandBuffer> commandBuffer_;
};

struct CommandQueueStatistics {
  uint32_t currentDrawCount = 0;
  uint32_t lastFrameDrawCount = 0;
};

class ICommandQueue {
 public:
  virtual ~ICommandQueue() = default;
  virtual std::shared_ptr<ICommandBuffer> createCommandBuffer(const CommandBufferDesc& desc,
                                                              Result* IGL_NULLABLE outResult) = 0;
  virtual SubmitHandle submit(const ICommandBuffer& commandBuffer, bool endOfFrame = false) = 0;
  [[nodiscard]] uint32_t getLastFrameDrawCount() const {
    return statistics_.lastFrameDrawCount;
  }
  void endFrame() {
    statistics_.lastFrameDrawCount = statistics_.currentDrawCount;
    statistics_.currentDrawCount = 0;
  }

 protected:
  void incrementDrawCount(uint32_t newDrawCount) {
    statistics_.currentDrawCount += newDrawCount;
  }

 private:
  CommandQueueStatistics statistics_;
};

