struct TextureFormatProperties {
  static TextureFormatProperties fromTextureFormat(TextureFormat format);

  enum Flags : uint8_t {
    Depth = 1 << 0,
    Stencil = 1 << 1,
    Compressed = 1 << 2,
    sRGB = 1 << 3,
    Integer = 1 << 4,
    HDR = 1 << 5,
    VariableLength = 1 << 6,
  };

  const char* IGL_NONNULL name = "Invalid";
  const TextureFormat format = TextureFormat::Invalid;
  const uint8_t componentsPerPixel = 1;
  const uint8_t bytesPerBlock = 1;
  const uint8_t blockWidth = 1;
  const uint8_t blockHeight = 1;
  const uint8_t blockDepth = 1;
  const uint8_t minBlocksX = 1;
  const uint8_t minBlocksY = 1;
  const uint8_t minBlocksZ = 1;
  const uint8_t numPlanes = 1;
  const uint8_t flags = 0;

  [[nodiscard]] bool isValid() const noexcept { return format != TextureFormat::Invalid; }
  [[nodiscard]] bool isCompressed() const noexcept { return (flags & Flags::Compressed) != 0; }
  [[nodiscard]] bool isInteger() const noexcept { return (flags & Flags::Integer) != 0; }
  [[nodiscard]] bool isSRGB() const noexcept { return (flags & Flags::sRGB) != 0; }
  [[nodiscard]] bool isHDR() const noexcept { return (flags & Flags::HDR) != 0; }
  [[nodiscard]] bool hasDepth() const noexcept { return (flags & Flags::Depth) != 0; }
  [[nodiscard]] bool hasStencil() const noexcept { return (flags & Flags::Stencil) != 0; }
  [[nodiscard]] bool hasColor() const noexcept { return !hasDepth() && !hasStencil(); }
  [[nodiscard]] bool isDepthOnly() const noexcept { return hasDepth() && !hasStencil(); }
  [[nodiscard]] bool isDepthOrDepthStencil() const noexcept { return hasDepth(); }
  [[nodiscard]] bool isStencilOnly() const noexcept { return !hasDepth() && hasStencil(); }
  [[nodiscard]] bool isDepthOrStencil() const noexcept { return (flags & Flags::Depth) != 0 || (flags & Flags::Stencil) != 0; }
  [[nodiscard]] bool isVariableLength() const noexcept { return (flags & Flags::VariableLength) != 0; }

  [[nodiscard]] uint32_t getRows(TextureRangeDesc range) const noexcept;
  [[nodiscard]] uint32_t getBytesPerRow(uint32_t texWidth) const noexcept;
  [[nodiscard]] uint32_t getBytesPerRow(TextureRangeDesc range) const noexcept;
  [[nodiscard]] size_t getBytesPerLayer(uint32_t texWidth,
                                        uint32_t texHeight,
                                        uint32_t texDepth,
                                        uint32_t bytesPerRow = 0) const noexcept;
  [[nodiscard]] size_t getBytesPerLayer(TextureRangeDesc range,
